<script lang="ts">
import {catalog,readingFor} from '../catalog';
import {works,date,authorNames,matchesRegion,type Region} from '../history';
let {region,selected,select}:{region:Region;selected:string;select:(id:string,jump?:boolean)=>void}=$props();
let search=$state(''),expanded=$state(false);
$effect(()=>{region;search;expanded=false;});
let filtered=$derived(works.filter(w=>matchesRegion(w,region)&&`${w.name} ${authorNames(w)} ${w.end}`.toLowerCase().includes(search.trim().toLowerCase())));
</script>
<section class="library"><div class="library-heading"><div><p class="eyebrow">A LIBRARY ACROSS TIME</p><h2>时代的书页</h2><p>按写作完成时间排列。写作、发表与后来的整理出版，分别标明。</p></div><input type="search" aria-label="搜索文献或作者" placeholder="搜索文献、作者…" bind:value={search}></div><div id="books">{#each (expanded||search.trim()?filtered:filtered.slice(0,6)) as w(w.id)}<button class="book-card" class:selected={selected===w.id} onclick={()=>{select(w.id,true);document.querySelector('#sky')?.scrollIntoView({block:'center'});}}><span class="book-year">{w.end.slice(0,4)} <span>✦</span></span><h3>{w.name}</h3><p>{authorNames(w)}</p><div><span>{w.dateLabel||'写作'} · {date(w.start)}{w.start===w.end?'':' — '+date(w.end)}</span><span>发表 · {w.published}</span></div><span class="catalog-summary">{catalog[w.id]?.metadata.status==='verified'?catalog[w.id].metadata.publisher+' · '+catalog[w.id].metadata.published:'豆瓣版本待核实'}</span><span class="book-action">{readingFor(w.id,w.name,authorNames(w)).provider==='weread'?'微信读书入口':'安娜检索'} · 查看详情与阅读入口 ↗</span></button>{/each}</div><div class="library-footer"><span>{filtered.length} 部文献 · 按年代排列</span>{#if filtered.length>6&&!search.trim()}<button onclick={()=>expanded=!expanded}>{expanded?'收起目录 ↑':`查看全部 ${filtered.length} 部文献 ↓`}</button>{/if}</div>{#if !filtered.length}<p>没有匹配的文献，试试其他书名或作者。</p>{/if}</section>
